?><section class="admin-page-title"><h1>信任设备</h1><p>登录一次后设备会自动保持登录；解绑后该设备需要重新登录。</p></section><?php if($message):?><div class="admin-card" style="color:#15803d;margin-bottom:1rem"><?php echo e($message);?></div><?php endif;?><section class="admin-card"><table class="admin-table"><thead><tr><th>设备</th><th>IP</th><th>首次信任</th><th>最近使用</th><th>状态</th><th>操作</th></tr></thead><tbody><?php foreach($devices as $device):?><tr><td style="max-width:360px;word-break:break-all"><?php echo e($device['device_name']??'浏览器');?></td><td><?php echo e($device['last_ip']??'');?></td><td><?php echo e($device['created_at']);?></td><td><?php echo e($device['last_seen_at']??'');?></td><td><?php echo $device['revoked_at']?'已解绑':'使用中';?></td><td><?php if(!$device['revoked_at']):?><form method="post"><?php echo csrf_field();?><input type="hidden" name="id" value="<?php echo (int)$device['id'];?>"><button class="btn btn-secondary" type="submit">解绑</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section><?php include __DIR__.'/footer.php';?>
